/**
 * Screen #27 — Available / Alternative Slot Selection
 * Displays complete system-generated candidates.
 *
 * AUTHORITATIVE M3 INVARIANTS:
 * - Each candidate is an INDIVISIBLE bundle: Time Slot + Qualified Therapist + Compatible Room.
 * - Selecting a candidate does NOT reserve any resource or create a session.
 * - Handles No-Availability cleanly, showing alternative candidates generated by backend engine.
 * - BR-M3-08: Supports rejecting individual alternatives, successive negotiation turns,
 *   declining all alternatives, detecting exhaustion, and finalizing session cancellation.
 * - Race-Safe: Uses request sequence tokens to discard stale out-of-order async responses.
 * - Negotiation-Isolated: Resets rejection list when search parameters change.
 */

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useLocation, useSearchParams } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { spaApi } from '../../features/m3-spa/api/spaApi';
import type { SchedulingCandidate, CandidateGenerationResult } from '../../features/m3-spa/types/spaTypes';
import {
  ChevronLeft,
  Clock,
  User,
  MapPin,
  Calendar,
  Sparkles,
  Check,
  AlertCircle,
  ArrowRight,
  RotateCcw,
  RefreshCw,
  XCircle,
  CheckCircle,
} from 'lucide-react';

interface NavigationState {
  result?: CandidateGenerationResult;
  treatmentId?: number;
  treatmentName?: string;
  durationMinutes?: number;
  preferredDate?: string;
  timeRangePreference?: string;
  customerNote?: string;
  rescheduleSessionId?: number;
}

export const SpaAlternativeSlotsPage: React.FC = () => {
  const { t } = useTranslation('customer');
  const navigate = useNavigate();
  const location = useLocation();
  const [searchParams] = useSearchParams();

  const navState = (location.state as NavigationState) || {};
  const treatmentIdFromQuery = searchParams.get('treatment') ? Number(searchParams.get('treatment')) : 1;
  const dateFromQuery = searchParams.get('date') || new Date().toISOString().split('T')[0];

  const [candidates, setCandidates] = useState<SchedulingCandidate[]>(navState.result?.candidates || []);
  const [alternativeCandidates, setAlternativeCandidates] = useState<SchedulingCandidate[]>(
    navState.result?.alternativeCandidates || []
  );
  const [selectedCandidate, setSelectedCandidate] = useState<SchedulingCandidate | null>(null);
  const [rejectedCandidateIds, setRejectedCandidateIds] = useState<string[]>([]);
  const [loading, setLoading] = useState<boolean>(!navState.result);
  const [cancelling, setCancelling] = useState<boolean>(false);
  const [cancellationComplete, setCancellationComplete] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  // Request sequence token to prevent out-of-order asynchronous responses from overwriting newer state
  const requestIdRef = useRef<number>(0);

  const treatmentId = navState.treatmentId || treatmentIdFromQuery;
  const preferredDate = navState.preferredDate || dateFromQuery;
  const rescheduleSessionId = navState.rescheduleSessionId;
  const customerNote = navState.customerNote;

  // Negotiation Isolation: Reset rejection memory if treatment or search date changes
  useEffect(() => {
    setRejectedCandidateIds([]);
    setSelectedCandidate(null);
  }, [treatmentId, preferredDate]);

  // If page was loaded directly without navigation state, fetch candidates from backend API
  useEffect(() => {
    if (!navState.result) {
      const currentReqId = ++requestIdRef.current;
      setLoading(true);
      spaApi
        .generateCandidates({
          treatmentId,
          preferredDate,
          flexibleWithDate: true,
          rescheduleSessionId,
        })
        .then((res) => {
          if (currentReqId !== requestIdRef.current) return; // Discard stale out-of-order response
          setCandidates(res.candidates || []);
          setAlternativeCandidates(res.alternativeCandidates || []);
        })
        .catch((err) => {
          if (currentReqId !== requestIdRef.current) return;
          setError(err instanceof Error ? err.message : 'Failed to retrieve available slots.');
        })
        .finally(() => {
          if (currentReqId === requestIdRef.current) {
            setLoading(false);
          }
        });
    }
  }, [navState.result, treatmentId, preferredDate, rescheduleSessionId]);

  /**
   * Reject an individual candidate bundle (BR-M3-08).
   * Accumulates rejectedCandidateIds, filters UI, and re-queries backend if visible pool is emptied.
   */
  const handleRejectCandidate = async (candidateId: string) => {
    const updatedRejected = [...rejectedCandidateIds, candidateId];
    setRejectedCandidateIds(updatedRejected);

    if (selectedCandidate?.candidateId === candidateId) {
      setSelectedCandidate(null);
    }

    const remainingCandidates = candidates.filter((c) => c.candidateId !== candidateId);
    const remainingAlternatives = alternativeCandidates.filter((c) => c.candidateId !== candidateId);
    setCandidates(remainingCandidates);
    setAlternativeCandidates(remainingAlternatives);

    // If both active pools are exhausted after rejection, re-query engine with excluded candidate IDs
    if (remainingCandidates.length === 0 && remainingAlternatives.length === 0) {
      const currentReqId = ++requestIdRef.current;
      setLoading(true);
      setError(null);
      try {
        const res = await spaApi.generateCandidates({
          treatmentId,
          preferredDate,
          flexibleWithDate: true,
          rejectedCandidateIds: updatedRejected,
          rescheduleSessionId,
        });
        if (currentReqId !== requestIdRef.current) return; // Discard stale out-of-order response
        setCandidates(res.candidates || []);
        setAlternativeCandidates(res.alternativeCandidates || []);
      } catch (err) {
        if (currentReqId !== requestIdRef.current) return;
        setError(err instanceof Error ? err.message : 'Failed to query scheduling engine for next alternatives.');
      } finally {
        if (currentReqId === requestIdRef.current) {
          setLoading(false);
        }
      }
    }
  };

  /**
   * Decline all alternatives or cancel when alternatives are exhausted (BR-M3-08).
   * Flow A (New booking): Safe client-side abandonment (navigates back to catalogue with 0 database changes).
   * Flow B (Reschedule): Server cancellation of persistent session (idempotent, frees resource locks).
   */
  const handleDeclineAllAlternatives = async () => {
    if (rescheduleSessionId) {
      setCancelling(true);
      setError(null);
      try {
        await spaApi.cancelSession(rescheduleSessionId);
        setCancellationComplete(true);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to cancel session on server.');
      } finally {
        setCancelling(false);
      }
    } else {
      // Flow A: New booking negotiation declined by customer: safely exit to spa catalogue
      navigate('/customer/spa');
    }
  };

  const handleSelectAndProceed = () => {
    if (!selectedCandidate) return;

    // Navigate to Screen 28 (Final Confirmation)
    navigate('/customer/spa/confirm', {
      state: {
        selectedCandidate,
        treatmentId,
        rescheduleSessionId,
        customerNote,
      },
    });
  };

  const isExhausted = !loading && candidates.length === 0 && alternativeCandidates.length === 0;

  if (cancellationComplete) {
    return (
      <div className="spa-alternative-slots-page" id="screen-27-cancellation-confirmed" style={{ maxWidth: '650px', margin: '40px auto', padding: '24px' }}>
        <div
          style={{
            backgroundColor: '#fff',
            border: '1px solid #e2e8f0',
            borderRadius: '12px',
            padding: '36px 24px',
            textAlign: 'center',
            boxShadow: '0 4px 12px rgba(0,0,0,0.05)',
          }}
        >
          <CheckCircle size={48} style={{ color: '#059669', margin: '0 auto 16px' }} />
          <h2 style={{ fontSize: '22px', fontWeight: 700, color: '#0f172a', marginBottom: '8px' }}>
            {t('spa.sessionCancelledTitle', 'Session Cancelled')}
          </h2>
          <p style={{ color: '#64748b', fontSize: '15px', lineHeight: 1.5, marginBottom: '24px' }}>
            {t(
              'spa.sessionCancelledDesc',
              'Your spa reservation has been officially cancelled following the decline of all offered alternatives. No resources remain reserved.'
            )}
          </p>
          <div style={{ display: 'flex', gap: '12px', justifyContent: 'center' }}>
            <button
              id="btn-view-my-sessions"
              className="hsw-btn hsw-btn-primary"
              onClick={() => navigate('/customer/spa/my-sessions')}
              style={{ padding: '10px 20px', fontWeight: 600 }}
            >
              {t('spa.viewMySessions', 'View My Sessions')}
            </button>
            <button
              id="btn-back-to-treatments"
              className="hsw-btn hsw-btn-secondary"
              onClick={() => navigate('/customer/spa')}
              style={{ padding: '10px 20px' }}
            >
              {t('spa.browseTreatments', 'Browse Treatments')}
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="spa-alternative-slots-page" id="screen-27-available-slots">
      {/* Header */}
      <div className="spa-alt-header">
        <button
          className="spa-back-btn"
          onClick={() =>
            navigate(
              `/customer/spa/book?treatment=${treatmentId}${
                rescheduleSessionId ? `&reschedule=${rescheduleSessionId}` : ''
              }`
            )
          }
          id="btn-back-to-preferences"
        >
          <ChevronLeft size={18} />
          <span>{t('spa.modifyCriteria', 'Modify Search Criteria')}</span>
        </button>
        <h1>{t('spa.candidateSelectionTitle', 'Available Scheduling Candidates')}</h1>
        <p className="spa-alt-subtitle">
          {t(
            'spa.candidateBundleExplanation',
            'Each option below is an indivisible bundle combining an open time slot, a certified practitioner, and a compatible treatment suite.'
          )}
        </p>
      </div>

      {rescheduleSessionId && (
        <div
          style={{
            backgroundColor: '#eff6ff',
            border: '1px solid #bfdbfe',
            borderRadius: '8px',
            padding: '12px 16px',
            marginBottom: '20px',
            display: 'flex',
            alignItems: 'center',
            gap: '12px',
            color: '#1e40af',
          }}
        >
          <RotateCcw size={18} />
          <span>
            {t(
              'spa.rescheduleSelectingNotice',
              'Selecting a replacement candidate will not alter your current booking until you confirm on the final screen.'
            )}
          </span>
        </div>
      )}

      {loading && (
        <div style={{ textAlign: 'center', padding: '60px 20px', color: '#64748b' }}>
          <RefreshCw size={32} className="spin" style={{ animation: 'spin 1s linear infinite' }} />
          <p style={{ marginTop: '12px' }}>{t('spa.queryingEngine', 'Consulting scheduling engine...')}</p>
        </div>
      )}

      {error && (
        <div
          style={{
            backgroundColor: '#fef2f2',
            border: '1px solid #fecaca',
            borderRadius: '8px',
            padding: '16px',
            color: '#b91c1c',
            marginBottom: '20px',
            display: 'flex',
            alignItems: 'center',
            gap: '10px',
          }}
        >
          <AlertCircle size={20} />
          <span>{error}</span>
        </div>
      )}

      {!loading && !error && (
        <div className="spa-alt-layout">
          <div className="spa-alt-main">
            {/* Primary Candidates Section */}
            {candidates.length > 0 && (
              <section className="spa-candidate-group">
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '16px' }}>
                  <Calendar size={18} style={{ color: '#0d9488' }} />
                  <h2 style={{ fontSize: '18px', fontWeight: 600, margin: 0 }}>
                    {t('spa.candidatesForDate', 'Open Slots for')} {preferredDate} ({candidates.length})
                  </h2>
                </div>

                <div className="spa-candidates-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '16px' }}>
                  {candidates.map((c) => {
                    const isSelected = selectedCandidate?.candidateId === c.candidateId;
                    return (
                      <div
                        key={c.candidateId}
                        className={`spa-candidate-card ${isSelected ? 'spa-candidate-card--selected' : ''}`}
                        onClick={() => setSelectedCandidate(c)}
                        id={`candidate-${c.candidateId}`}
                        style={{
                          border: isSelected ? '2px solid #0d9488' : '1px solid #e2e8f0',
                          borderRadius: '10px',
                          padding: '16px',
                          cursor: 'pointer',
                          backgroundColor: isSelected ? '#f0fdfa' : '#fff',
                          boxShadow: isSelected ? '0 4px 12px rgba(13, 148, 136, 0.15)' : 'none',
                          transition: 'all 0.2s ease',
                          display: 'flex',
                          flexDirection: 'column',
                          justifyContent: 'space-between',
                        }}
                      >
                        <div>
                          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '10px' }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                              <Clock size={16} style={{ color: '#0d9488' }} />
                              <span style={{ fontSize: '16px', fontWeight: 700, color: '#0f172a' }}>
                                {c.startTime} – {c.endTime}
                              </span>
                            </div>
                            {isSelected && (
                              <span style={{ backgroundColor: '#0d9488', color: '#fff', borderRadius: '50%', padding: '2px', display: 'flex' }}>
                                <Check size={14} />
                              </span>
                            )}
                          </div>

                          <div style={{ fontSize: '13px', color: '#475569', display: 'flex', flexDirection: 'column', gap: '6px' }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                              <User size={14} style={{ color: '#64748b' }} />
                              <span><strong>{t('spa.therapist', 'Therapist')}:</strong> {c.therapistName}</span>
                            </div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                              <MapPin size={14} style={{ color: '#64748b' }} />
                              <span><strong>{t('spa.suite', 'Suite')}:</strong> {c.roomName}</span>
                            </div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '6px', fontSize: '12px', color: '#64748b', marginTop: '4px' }}>
                              <Sparkles size={13} style={{ color: '#0d9488' }} />
                              <span>{c.durationMinutes} {t('spa.minutes', 'min')} · {c.treatmentName}</span>
                            </div>
                          </div>
                        </div>

                        <div style={{ marginTop: '12px', paddingTop: '10px', borderTop: '1px solid #f1f5f9', display: 'flex', justifyContent: 'flex-end' }}>
                          <button
                            type="button"
                            id={`btn-reject-candidate-${c.candidateId}`}
                            onClick={(e) => {
                              e.stopPropagation();
                              handleRejectCandidate(c.candidateId);
                            }}
                            style={{
                              background: 'transparent',
                              border: 'none',
                              color: '#94a3b8',
                              fontSize: '12px',
                              cursor: 'pointer',
                              display: 'flex',
                              alignItems: 'center',
                              gap: '4px',
                            }}
                            title={t('spa.rejectThisSlot', 'Dismiss this candidate')}
                          >
                            <XCircle size={14} />
                            <span>{t('spa.reject', 'Dismiss')}</span>
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </section>
            )}

            {/* Alternative Candidates Section */}
            {alternativeCandidates.length > 0 && (
              <section className="spa-alternative-group" style={{ marginTop: candidates.length > 0 ? '28px' : '0' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '16px' }}>
                  <Sparkles size={18} style={{ color: '#0d9488' }} />
                  <h3 style={{ fontSize: '16px', fontWeight: 600, margin: 0, color: '#334155' }}>
                    {t('spa.alternativeOptions', 'Alternative Verified Candidates (Nearest Days)')}
                  </h3>
                </div>

                <div className="spa-candidates-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '16px' }}>
                  {alternativeCandidates.map((c) => {
                    const isSelected = selectedCandidate?.candidateId === c.candidateId;
                    return (
                      <div
                        key={c.candidateId}
                        className={`spa-candidate-card ${isSelected ? 'spa-candidate-card--selected' : ''}`}
                        onClick={() => setSelectedCandidate(c)}
                        id={`candidate-${c.candidateId}`}
                        style={{
                          border: isSelected ? '2px solid #0d9488' : '1px dashed #cbd5e1',
                          borderRadius: '10px',
                          padding: '16px',
                          cursor: 'pointer',
                          backgroundColor: isSelected ? '#f0fdfa' : '#fafafa',
                          boxShadow: isSelected ? '0 4px 12px rgba(13, 148, 136, 0.15)' : 'none',
                          transition: 'all 0.2s ease',
                          display: 'flex',
                          flexDirection: 'column',
                          justifyContent: 'space-between',
                        }}
                      >
                        <div>
                          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '10px' }}>
                            <div>
                              <span style={{ fontSize: '11px', fontWeight: 600, color: '#0d9488', textTransform: 'uppercase', letterSpacing: '0.5px' }}>
                                {c.date}
                              </span>
                              <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginTop: '2px' }}>
                                <Clock size={15} style={{ color: '#0d9488' }} />
                                <span style={{ fontSize: '15px', fontWeight: 700, color: '#0f172a' }}>
                                  {c.startTime} – {c.endTime}
                                </span>
                              </div>
                            </div>
                            {isSelected && (
                              <span style={{ backgroundColor: '#0d9488', color: '#fff', borderRadius: '50%', padding: '2px', display: 'flex' }}>
                                <Check size={14} />
                              </span>
                            )}
                          </div>

                          <div style={{ fontSize: '13px', color: '#475569', display: 'flex', flexDirection: 'column', gap: '4px' }}>
                            <div><strong>{t('spa.therapist', 'Therapist')}:</strong> {c.therapistName}</div>
                            <div><strong>{t('spa.suite', 'Suite')}:</strong> {c.roomName}</div>
                          </div>
                        </div>

                        <div style={{ marginTop: '12px', paddingTop: '10px', borderTop: '1px solid #f1f5f9', display: 'flex', justifyContent: 'flex-end' }}>
                          <button
                            type="button"
                            id={`btn-reject-candidate-${c.candidateId}`}
                            onClick={(e) => {
                              e.stopPropagation();
                              handleRejectCandidate(c.candidateId);
                            }}
                            style={{
                              background: 'transparent',
                              border: 'none',
                              color: '#94a3b8',
                              fontSize: '12px',
                              cursor: 'pointer',
                              display: 'flex',
                              alignItems: 'center',
                              gap: '4px',
                            }}
                            title={t('spa.rejectThisSlot', 'Dismiss this alternative')}
                          >
                            <XCircle size={14} />
                            <span>{t('spa.reject', 'Dismiss')}</span>
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </section>
            )}

            {/* Exhaustion State (BR-M3-08) */}
            {isExhausted && (
              <div
                id="spa-alternatives-exhausted-panel"
                style={{
                  backgroundColor: '#fef2f2',
                  border: '1px solid #fecaca',
                  borderRadius: '12px',
                  padding: '32px 24px',
                  textAlign: 'center',
                  marginBottom: '24px',
                }}
              >
                <AlertCircle size={40} style={{ color: '#dc2626', margin: '0 auto 12px' }} />
                <h3 style={{ margin: '0 0 8px', color: '#991b1b', fontSize: '18px', fontWeight: 700 }}>
                  {t('spa.allAlternativesExhaustedTitle', 'All Alternative Candidates Exhausted / Declined')}
                </h3>
                <p style={{ margin: '0 0 20px', color: '#7f1d1d', fontSize: '14px', maxWidth: '540px', marginLeft: 'auto', marginRight: 'auto', lineHeight: 1.5 }}>
                  {t(
                    'spa.allAlternativesExhaustedDesc',
                    'No viable therapist and suite bundles remain within the search window for this treatment. In accordance with scheduling policy, you may cancel this reservation or adjust your stay constraints.'
                  )}
                </p>

                <div style={{ display: 'flex', gap: '12px', justifyContent: 'center', flexWrap: 'wrap' }}>
                  {rescheduleSessionId ? (
                    <button
                      type="button"
                      id="btn-cancel-exhausted-session"
                      className="hsw-btn"
                      onClick={handleDeclineAllAlternatives}
                      disabled={cancelling}
                      style={{
                        backgroundColor: '#dc2626',
                        color: '#fff',
                        padding: '10px 20px',
                        borderRadius: '8px',
                        border: 'none',
                        fontWeight: 600,
                        cursor: cancelling ? 'not-allowed' : 'pointer',
                      }}
                    >
                      {cancelling ? t('spa.cancelling', 'Cancelling...') : t('spa.cancelSession', 'Cancel Session Reservation')}
                    </button>
                  ) : (
                    <button
                      type="button"
                      id="btn-cancel-exhausted-session"
                      className="hsw-btn"
                      onClick={handleDeclineAllAlternatives}
                      style={{
                        backgroundColor: '#dc2626',
                        color: '#fff',
                        padding: '10px 20px',
                        borderRadius: '8px',
                        border: 'none',
                        fontWeight: 600,
                        cursor: 'pointer',
                      }}
                    >
                      {t('spa.cancelBookingAttempt', 'Cancel Booking Attempt')}
                    </button>
                  )}
                  <button
                    type="button"
                    id="btn-adjust-criteria"
                    className="hsw-btn hsw-btn-secondary"
                    onClick={() =>
                      navigate(
                        `/customer/spa/book?treatment=${treatmentId}${
                          rescheduleSessionId ? `&reschedule=${rescheduleSessionId}` : ''
                        }`
                      )
                    }
                    style={{ padding: '10px 20px' }}
                  >
                    {t('spa.adjustCriteria', 'Adjust Date & Time Constraints')}
                  </button>
                </div>
              </div>
            )}
          </div>

          {/* Sidebar / Bottom Action Drawer */}
          {!isExhausted && (
            <div className="spa-alt-sidebar" style={{ minWidth: '280px', marginTop: '20px' }}>
              <div style={{ backgroundColor: 'var(--surface)', border: '1px solid var(--border-subtle)', borderRadius: '12px', padding: '20px', position: 'sticky', top: '20px' }}>
                <h3 style={{ margin: '0 0 14px', fontSize: '16px' }}>{t('spa.selectedCandidateBundle', 'Selected Candidate')}</h3>

                {selectedCandidate ? (
                  <div style={{ fontSize: '14px', display: 'flex', flexDirection: 'column', gap: '10px', marginBottom: '18px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span style={{ color: '#64748b' }}>{t('spa.date', 'Date')}</span>
                      <strong>{selectedCandidate.date}</strong>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span style={{ color: '#64748b' }}>{t('spa.time', 'Time')}</span>
                      <strong>{selectedCandidate.startTime} – {selectedCandidate.endTime}</strong>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span style={{ color: '#64748b' }}>{t('spa.therapist', 'Therapist')}</span>
                      <strong>{selectedCandidate.therapistName}</strong>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span style={{ color: '#64748b' }}>{t('spa.suite', 'Suite')}</span>
                      <strong>{selectedCandidate.roomName}</strong>
                    </div>

                    <div style={{ backgroundColor: '#f0fdfa', border: '1px solid #ccfbf1', borderRadius: '6px', padding: '10px', fontSize: '12px', color: '#0f766e', marginTop: '6px' }}>
                      <Check size={14} style={{ display: 'inline', marginRight: '4px', verticalAlign: 'text-bottom' }} />
                      {t('spa.indivisibleConfirmed', 'Indivisible bundle matched by scheduling engine.')}
                    </div>
                  </div>
                ) : (
                  <div style={{ color: '#94a3b8', fontSize: '13px', fontStyle: 'italic', marginBottom: '18px' }}>
                    {t('spa.pleaseSelectCandidate', 'Please select one candidate bundle above to continue.')}
                  </div>
                )}

                <button
                  className="hsw-btn hsw-btn-primary"
                  disabled={!selectedCandidate}
                  onClick={handleSelectAndProceed}
                  id="btn-proceed-to-confirm"
                  style={{
                    width: '100%',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    gap: '8px',
                    padding: '12px',
                    fontWeight: 600,
                    opacity: selectedCandidate ? 1 : 0.6,
                    cursor: selectedCandidate ? 'pointer' : 'not-allowed',
                  }}
                >
                  <span>{t('spa.proceedToConfirmation', 'Proceed to Confirmation')}</span>
                  <ArrowRight size={16} />
                </button>

                <button
                  type="button"
                  id="btn-decline-all-alternatives"
                  className="hsw-btn"
                  onClick={handleDeclineAllAlternatives}
                  disabled={cancelling}
                  style={{
                    width: '100%',
                    marginTop: '10px',
                    padding: '10px',
                    background: '#fff',
                    border: '1px solid #fecaca',
                    color: '#dc2626',
                    borderRadius: '8px',
                    fontSize: '13px',
                    fontWeight: 500,
                    cursor: cancelling ? 'not-allowed' : 'pointer',
                  }}
                >
                  {cancelling ? t('spa.cancelling', 'Cancelling...') : t('spa.declineAllAlternatives', 'Decline All Alternatives')}
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};
